mapper.update:
UPDATE invoice_import_task
SET status = #{status}, total_count = #{totalCount}, success_count = #{successCount},
    failure_count = #{failureCount}, finished_at = #{finishedAt}
WHERE id = #{id}

mapper.select:
SELECT id, task_id, row_no, taxpayer_id, error_code, error_message, raw_data_json, created_at
FROM invoice_import_row_error
WHERE task_id = #{taskId}
ORDER BY row_no ASC, id ASC
LIMIT #{pageSize} OFFSET #{offset}
